{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Scale input embeddings by fixed per-category training-frequency factors clip((median positive item count / item count)^0.1, 0.8, 1.2). This may reduce frequent-item dominance while preserving learned embeddings, GRU topology, candidate scoring, loss, and optimizer. Factors are checkpoint buffers; the generated predictor imports the updated model class and restores them through its existing state_dict loader.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"input_rarity\", torch.ones(itemnum + 1))\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq) * self.input_rarity[seq].unsqueeze(-1))"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq) * self.input_rarity[seq].unsqueeze(-1))"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    item_counts = np.zeros(itemnum + 1, dtype=np.int64)\n    for history in user_train.values():\n        np.add.at(item_counts, np.asarray(history, dtype=np.int64), 1)\n    observed = item_counts > 0\n    observed[0] = False\n    rarity = np.ones(itemnum + 1, dtype=np.float32)\n    if observed.any():\n        median_count = float(np.median(item_counts[observed]))\n        rarity[observed] = np.clip(\n            (median_count / item_counts[observed]) ** 0.1, 0.8, 1.2\n        ).astype(np.float32)\n    rarity[0] = 0.0\n    with torch.no_grad():\n        model.input_rarity.copy_(torch.as_tensor(rarity, device=device))\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Add fixed training-frequency input scaling, saved in each category's single checkpoint and restored automatically during prediction."
}
